// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia, "Times New Roman", Times, serif';
var MAG = '#e6007e';
var BASE_FILL = '#d9d3c8';
var HL_FILL = '#e9b34a';
var HL_STROKE = '#8a5a12';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 415;
draw.viewbox(0, 0, W, H);

var PX0 = 46, PX1 = 1096, PY0 = 30, PY1 = 330;
var XZERO = 1078, KPP = (XZERO - 50) / 220;   // px per ppm  (xOf(220) = 50)
function xOf(d) { return XZERO - d * KPP; }
function dOf(x) { return (XZERO - x) / KPP; }

/* ── background panel ─────────────────────────────────────────────── */
var grad = draw.gradient('linear', function (add) {
  add.stop(0, '#fbf0cd');
  add.stop(0.55, '#fdf8e6');
  add.stop(1, '#fffefb');
}).from(0, 0).to(0, 1);
draw.rect(PX1 - PX0, PY1 - PY0).move(PX0, PY0).fill(grad);

/* ── gridlines ────────────────────────────────────────────────────── */
var TICKS = [220, 200, 180, 160, 140, 120, 100, 80, 60, 40, 20, 0];
TICKS.forEach(function (d) {
  if (d === 220) return;
  draw.line(xOf(d), PY0, xOf(d), PY1).stroke({ color: '#cfc9bd', width: 0.9 });
});

/* ── transparent drag overlay (below bars) ────────────────────────── */
var overlay = draw.rect(PX1 - PX0, PY1 - PY0).move(PX0, PY0).fill('#fff').opacity(0);
overlay.css('cursor', 'ew-resize');

/* ── panel border ─────────────────────────────────────────────────── */
draw.rect(PX1 - PX0, PY1 - PY0).move(PX0, PY0).fill('none')
  .stroke({ color: '#2b2b2b', width: 1.3 });

/* ── axis ticks + labels ──────────────────────────────────────────── */
TICKS.forEach(function (d) {
  draw.line(xOf(d), PY1, xOf(d), PY1 + 7).stroke({ color: '#222', width: 1.4 });
  draw.text(String(d)).font({ family: SERIF, size: 19, anchor: 'middle' })
    .attr({ x: xOf(d), y: 354, fill: '#111', 'dominant-baseline': 'central' });
});
draw.text('ppm').font({ family: SERIF, size: 17, anchor: 'start' })
  .attr({ x: 1104, y: 354, fill: '#111', 'dominant-baseline': 'central' });
draw.text('Chemical shift (').font({ family: SERIF, size: 19, anchor: 'end' })
  .attr({ x: 594, y: 389, fill: '#111', 'dominant-baseline': 'central' });
draw.text('\u03b4').font({ family: SERIF, size: 19, anchor: 'middle' })
  .attr({ x: 601, y: 389, fill: '#111', 'dominant-baseline': 'central', 'font-style': 'italic' });
draw.text(')').font({ family: SERIF, size: 19, anchor: 'start' })
  .attr({ x: 608, y: 389, fill: '#111', 'dominant-baseline': 'central' });
draw.text('deshielded \u2190 higher \u03b4').font({ family: SERIF, size: 13, anchor: 'start' })
  .attr({ x: 50, y: 389, fill: '#b3006b', 'dominant-baseline': 'central' });

/* ── intensity axis (no numbers) ──────────────────────────────────── */
draw.line(30, 196, 30, 80).stroke({ color: MAG, width: 3, linecap: 'round' });
draw.polygon('30,64 23,82 37,82').fill(MAG);
draw.text('Intensity').font({ family: SERIF, size: 20, anchor: 'middle' })
  .attr({ x: 0, y: 0, fill: '#111', 'dominant-baseline': 'central', transform: 'translate(20,268) rotate(-90)' });

/* ── label builder (handles subscripts without tspan reliance) ────── */
function mkLabel(parent, spec, cx, cy, size) {
  var g = parent.group();
  var pieces = [], total = 0;
  spec.forEach(function (p) {
    var fs = p.sub ? size * 0.72 : size;
    var t = g.text(p.t).font({ family: SERIF, size: fs, anchor: 'start' })
      .attr({ x: 0, y: 0, fill: '#1a1a1a', 'dominant-baseline': 'central' });
    var w;
    try { w = t.node.getComputedTextLength(); } catch (e) { w = 0; }
    if (!w) w = p.t.length * fs * 0.55;
    pieces.push({ t: t, w: w, dy: p.sub ? size * 0.26 : 0 });
    total += w;
  });
  var x = -total / 2;
  pieces.forEach(function (p) { p.t.attr({ x: x, y: p.dy }); x += p.w; });
  g.attr('transform', 'translate(' + cx + ',' + cy + ')');
  return g;
}

/* ── the eleven bands ─────────────────────────────────────────────── */
var BANDS = [
  { plain: 'C=O', lo: 160, hi: 220, row: 0, spec: [{ t: 'C=O' }],
    note: 'Carbonyl carbons (aldehydes, ketones, acids, esters, amides) absorb from about 160 to 220 ppm \u2014 far downfield of everything else. A \u03c0 bond plus a very electronegative oxygen strips electron density from the carbon, so it is the most deshielded carbon in an ordinary organic molecule. A peak above 160 ppm is therefore nearly diagnostic.' },
  { plain: 'C=C', lo: 107, hi: 150, row: 1, spec: [{ t: 'C=C' }],
    note: 'Alkene carbons resonate near 107\u2013150 ppm. sp\u00b2 hybridisation and circulating \u03c0 electrons deshield them well beyond the sp\u00b3 region, but this window overlaps the aromatic band almost completely.' },
  { plain: 'Aromatic', lo: 110, hi: 148, row: 2, spec: [{ t: 'Aromatic' }],
    note: 'Benzene-ring carbons fall near 110\u2013148 ppm, sitting right on top of the alkene range. Chemical shift alone cannot separate aromatic from alkene carbons \u2014 you need the \u00b9H spectrum, molecular symmetry, or the formula to decide.' },
  { plain: 'C\u2261N', lo: 120, hi: 130, row: 3, spec: [{ t: 'C\u2261N' }],
    note: 'Nitrile carbons occupy a narrow 120\u2013130 ppm window \u2014 precise, but buried inside the crowded alkene/aromatic band, so a peak there is ambiguous on its own.' },
  { plain: 'C\u2261C', lo: 80, hi: 95, row: 4, spec: [{ t: 'C\u2261C' }],
    note: 'Alkyne carbons appear around 80\u201395 ppm \u2014 upfield of alkenes even though they are more unsaturated. The cylindrical \u03c0 system shields the carbon along the bond axis, cancelling part of the expected deshielding.' },
  { plain: 'C\u2014O', lo: 68, hi: 88, row: 5, spec: [{ t: 'C\u2014O' }],
    note: 'A carbon singly bonded to oxygen (alcohol or ether) sits near 68\u201388 ppm. The electronegative oxygen pulls \u03c3 electron density away, shifting the carbon roughly 50 ppm downfield of a plain alkane carbon.' },
  { plain: 'C\u2014N', lo: 55, hi: 78, row: 6, spec: [{ t: 'C\u2014N' }],
    note: 'Carbons bonded to nitrogen appear near 55\u201378 ppm. Nitrogen is less electronegative than oxygen, so the inductive deshielding \u2014 and the downfield shift \u2014 is smaller than for C\u2014O.' },
  { plain: 'C\u2014Hal', lo: 10, hi: 80, row: 7, spec: [{ t: 'C\u2014Hal' }],
    note: 'Halogen-bearing carbons span a huge 10\u201380 ppm window because the halogens differ so much: fluorine drives the carbon strongly downfield, while iodine\u2019s heavy-atom effect can push it upfield of a normal alkane. A very wide band means a very weak diagnosis.' },
  { plain: '\u2014CH\u2014', lo: 42, hi: 60, row: 8, spec: [{ t: '\u2014CH\u2014' }],
    note: 'Methine (CH) carbons typically appear near 42\u201360 ppm. Each extra alkyl substituent adds roughly 10 ppm, which is why CH sits downfield of CH\u2082 and CH\u2083.' },
  { plain: '\u2014CH\u2082\u2014', lo: 28, hi: 50, row: 9, spec: [{ t: '\u2014CH' }, { t: '2', sub: true }, { t: '\u2014' }],
    note: 'Methylene carbons resonate around 28\u201350 ppm \u2014 one substituent less than CH, so about 10 ppm further upfield.' },
  { plain: '\u2014CH\u2083', lo: 18, hi: 30, row: 10, spec: [{ t: '\u2014CH' }, { t: '3', sub: true }],
    note: 'Methyl carbons are the least substituted and least deshielded, hugging the right edge near 18\u201330 ppm. Everything to their left has been deshielded by \u03c0 bonding or an electronegative neighbour.' }
];

var BAR_H = 22;
function cyOf(row) { return 312 - row * 27; }

BANDS.forEach(function (b) {
  var x0 = xOf(b.hi), x1 = xOf(b.lo), cy = cyOf(b.row);
  var g = draw.group();
  b.g = g;
  b.rect = g.rect(x1 - x0, BAR_H).move(x0, cy - BAR_H / 2).radius(2).fill(BASE_FILL).stroke('none');
  b.x0 = x0; b.x1 = x1; b.cy = cy;
  mkLabel(g, b.spec, (x0 + x1) / 2, cy, 16.5);
  g.css('cursor', 'pointer');
  g.on('mouseover', function () { hoverBand(b); });
  g.on('mousemove', function (e) {
    showTooltip(b.plain + ':  ' + b.hi + '\u2013' + b.lo + ' ppm  (span ' + (b.hi - b.lo) + ' ppm)', e);
  });
  g.on('mouseout', function () { hideTooltip(); clearProj(); render(); });
  g.on('click', function () { showPopup(b.plain + '   (' + b.hi + '\u2013' + b.lo + ' ppm)', b.note); });
});

/* ── projection layer (hover) ─────────────────────────────────────── */
var projG = draw.group();
function clearProj() { projG.clear(); }
function hoverBand(b) {
  clearProj();
  projG.rect(b.x1 - b.x0, 344 - (b.cy - BAR_H / 2)).move(b.x0, b.cy - BAR_H / 2)
    .fill({ color: HL_FILL, opacity: 0.18 }).stroke('none');
  [b.x0, b.x1].forEach(function (x) {
    projG.line(x, b.cy + BAR_H / 2, x, 344).stroke({ color: HL_STROKE, width: 1, dasharray: '3,3' });
  });
  projG.rect(b.x1 - b.x0, 7).move(b.x0, 331).fill({ color: HL_STROKE, opacity: 0.75 });
  b.g.opacity(1);
  b.rect.stroke({ color: HL_STROKE, width: 1.1 });
}

/* ── cursor ───────────────────────────────────────────────────────── */
var cursorG = draw.group();
var cLine = cursorG.line(0, PY0, 0, PY1 + 8).stroke({ color: MAG, width: 2 });
var cBub = cursorG.rect(58, 22).move(0, 4).radius(4).fill(MAG);
var cTxt = cursorG.text('\u03b4 120').font({ family: 'sans-serif', size: 12.5, anchor: 'middle' })
  .attr({ x: 0, y: 15, fill: '#fff', 'dominant-baseline': 'central' });
cursorG.css('cursor', 'ew-resize');
cursorG.opacity(0);

/* ── state ────────────────────────────────────────────────────────── */
var delta = 220;
var revealed = false;

function render() {
  var hits = [];
  BANDS.forEach(function (b) {
    var inside = (delta >= b.lo && delta <= b.hi);
    if (inside) hits.push(b);
    if (!revealed) {
      b.g.opacity(1); b.rect.fill(BASE_FILL).stroke('none');
    } else if (inside) {
      b.g.opacity(1); b.rect.fill(HL_FILL).stroke({ color: HL_STROKE, width: 1.2 });
    } else {
      b.g.opacity(0.26); b.rect.fill(BASE_FILL).stroke('none');
    }
  });
  var x = xOf(delta);
  cLine.plot(x, PY0, x, PY1 + 8);
  var bx = Math.max(PX0 + 2, Math.min(PX1 - 60, x - 29));
  cBub.move(bx, 4);
  cTxt.attr({ x: bx + 29, y: 15 });
  cTxt.text('\u03b4 ' + delta);
  cursorG.opacity(revealed ? 1 : 0);

  var list = document.getElementById('hitList');
  if (!revealed) {
    list.innerHTML = '<span style="color:#888">move the cursor to test a peak position</span>';
  } else if (!hits.length) {
    list.innerHTML = '<span style="color:#888">\u2014 no common carbon environment here \u2014</span>';
  } else {
    list.innerHTML = hits.map(function (b) {
      return '\u2022 ' + b.plain + ' <span style="color:#999">(' + b.hi + '\u2013' + b.lo + ')</span>';
    }).join('<br>');
  }
}

function setDelta(d) {
  delta = Math.max(0, Math.min(220, Math.round(d)));
  var inp = document.getElementById('shiftCursorInput');
  var out = document.getElementById('shiftCursorVal');
  if (inp) inp.value = delta;
  if (out) out.value = delta;
  render();
}

function update_shiftCursor(v) { revealed = true; setDelta(v); }

/* ── dragging ─────────────────────────────────────────────────────── */
var dragging = false;
function viewX(clientX, clientY) {
  var pt = draw.node.createSVGPoint();
  pt.x = clientX; pt.y = clientY;
  var m = draw.node.getScreenCTM();
  if (!m) return 0;
  return pt.matrixTransform(m.inverse()).x;
}
function fromEvent(e) { revealed = true; setDelta(dOf(viewX(e.clientX, e.clientY))); }
overlay.on('mousedown', function (e) { dragging = true; fromEvent(e); e.preventDefault(); });
cursorG.on('mousedown', function (e) { dragging = true; fromEvent(e); e.preventDefault(); });
document.addEventListener('mousemove', function (e) { if (dragging) fromEvent(e); });
document.addEventListener('mouseup', function () { dragging = false; });

/* ── demo steps ───────────────────────────────────────────────────── */
var STEPS = [
  { title: 'Read the reversed scale', narration: 'The axis runs backwards: 220 ppm on the left, 0 ppm on the right. Every gray bar marks the window where one kind of carbon absorbs; bar height is only stacking, not intensity.', state: { shiftCursor: 220 } },
  { title: 'Alkane country (10\u201340 ppm)', narration: 'Park the cursor near 25 ppm and only the plain sp\u00b3 bars \u2014 CH\u2083, CH\u2082, and C\u2014Hal \u2014 light up. Unsubstituted carbons hug the right end of the chart.', state: { shiftCursor: 25 } },
  { title: 'A crowded, ambiguous region (70 ppm)', narration: 'At 70 ppm the cursor cuts C\u2014O, C\u2014N, C\u2014Hal, C\u2261C, and \u2014CH\u2014 all at once. One peak here does not identify a group; it narrows the field and you need other evidence to choose.', state: { shiftCursor: 70 } },
  { title: 'The sp\u00b2 / aromatic band (125 ppm)', narration: 'Slide left to 125 ppm and the alkane bars go dark while C=C, Aromatic, and C\u2261N light up. Doubly bonded and ring carbons cluster in a band of their own.', state: { shiftCursor: 125 } },
  { title: 'Carbonyl carbons stand alone', narration: 'Past 160 ppm only C=O remains. A peak above 160 ppm is nearly diagnostic \u2014 the most deshielded carbon in an ordinary organic molecule is the one double-bonded to oxygen.', state: { shiftCursor: 190 } },
  { title: 'Inspect one band', narration: 'Hover any bar to read its endpoints and see its window projected onto the axis. Compare C\u2014Hal\u2019s huge span against CH\u2083\u2019s narrow one: some environments are far more diagnostic than others.', state: { shiftCursor: 120 } }
];
var stepIdx = 0;

function applyStep(i, reveal) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  var s = STEPS[stepIdx];
  if (reveal) revealed = true;
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + STEPS.length + ' \u00b7 ' + s.title;
  setDelta(s.state.shiftCursor);
}
function prevStep() { applyStep(stepIdx - 1, true); }
function nextStep() { applyStep(stepIdx + 1, true); }

function showInsight() {
  showPopup('Key insight',
    'A \u00b9\u00b3C chemical shift is an overlapping range, not an address: the farther left (higher \u03b4) a carbon appears, the more it has been deshielded by \u03c0 bonding or an electronegative neighbour. Assignment means intersecting the observed position with every band it touches \u2014 sometimes one group (above 160 ppm), often five at once (near 70 ppm).');
}

/* ── init: faithful static default, cursor hidden until interaction ─ */
applyStep(0, false);
render();

window.__markRendered();
// @FIGURE_CODE_END

